package com.nextrade.tests; import org.junit.jupiter.api.*; import java.nio.file.*; import static org.junit.jupiter.api.Assertions.*; class ArchitectureRulesTest {@Test void noEngineServiceImport(){Path p=Path.of("..","nextrade-engine","src","main","java");if(Files.exists(p)){try(var s=Files.walk(p)){boolean bad=s.filter(x->x.toString().endsWith(".java")).anyMatch(this::containsServiceImport);assertFalse(bad,"Engine must not depend on service module");}catch(Exception e){fail(e);}}}@Test void singleJwtPipelineRule(){Path p=Path.of("..","nextrade-api","src","main","java","com","nextrade","api","security","SecurityConfig.java");if(Files.exists(p)){try{String s=Files.readString(p);assertFalse(s.contains("oauth2ResourceServer"));assertTrue(s.contains("JwtAuthenticationFilter"));}catch(Exception e){fail(e);}}}private boolean containsServiceImport(Path p){try{return Files.readString(p).contains("com.nextrade.service");}catch(Exception e){return true;}}}
